import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { getById } from "../services/schemeService";
import { FaTag, FaMapMarkerAlt, FaCheckCircle, FaFileAlt, FaArrowLeft } from "react-icons/fa";

const SchemeDetails = () => {

    const { id } = useParams();
    const [scheme, setScheme] = useState(null);

    useEffect(() => {
        fetchScheme();
    }, [id]);   // ✅ important dependency

    const fetchScheme = async () => {
        try {
            const data = await getById(id);
            setScheme(data);
        } catch (error) {
            console.error("Error loading scheme:", error);
        }
    };

    if (!scheme) return <h2>Loading...</h2>;

    return (
        <div className="details-container">

            <Link to="/" className="back-btn">
                <FaArrowLeft /> Back
            </Link>

            <h2>{scheme.schemeName}</h2>

            <img
                src={process.env.PUBLIC_URL + scheme.image}
                alt={scheme.schemeName}
            />

            <p><FaTag className="icon" /> <strong>Category:</strong> {scheme.category}</p>
            <p><FaMapMarkerAlt className="icon" /> <strong>State:</strong> {scheme.state}</p>
            <p><strong>Description:</strong> {scheme.description}</p>
            <p><FaCheckCircle className="icon" /> <strong>Eligibility:</strong> {scheme.eligibility}</p>
            <p><FaCheckCircle className="icon" /> <strong>Benefits:</strong> {scheme.benefits}</p>
            <p><FaFileAlt className="icon" /> <strong>Required Documents:</strong> {scheme.requiredDocuments}</p>

            <a
                href={scheme.officialLink}
                target="_blank"
                rel="noreferrer"
                className="btn"
            >
                Apply on Official Website
            </a>

        </div>
    );
};

export default SchemeDetails;
